    ap_sync_reg_Gaussian_Filter_U0_ap_ready_assign_proc : process(ap_clk)
    begin
        if (ap_clk'event and ap_clk =  '1') then
            if (ap_rst_n_inv = '1') then
                ap_sync_reg_Gaussian_Filter_U0_ap_ready <= ap_const_logic_0;
            else
                if (((ap_sync_ready and ap_start) = ap_const_logic_1)) then 
                    ap_sync_reg_Gaussian_Filter_U0_ap_ready <= ap_const_logic_0;
                else 
                    ap_sync_reg_Gaussian_Filter_U0_ap_ready <= ap_sync_Gaussian_Filter_U0_ap_ready;
                end if; 
            end if;
        end if;
    end process;


    ap_sync_reg_entry_proc_U0_ap_ready_assign_proc : process(ap_clk)
    begin
        if (ap_clk'event and ap_clk =  '1') then
            if (ap_rst_n_inv = '1') then
                ap_sync_reg_entry_proc_U0_ap_ready <= ap_const_logic_0;
            else
                if (((ap_sync_ready and ap_start) = ap_const_logic_1)) then 
                    ap_sync_reg_entry_proc_U0_ap_ready <= ap_const_logic_0;
                else 
                    ap_sync_reg_entry_proc_U0_ap_ready <= ap_sync_entry_proc_U0_ap_ready;
                end if; 
            end if;
        end if;
    end process;

    Gaussian_Filter_U0_ap_continue <= ap_const_logic_1;
    Gaussian_Filter_U0_ap_start <= ((ap_sync_reg_Gaussian_Filter_U0_ap_ready xor ap_const_logic_1) and ap_start and ap_const_logic_1);
    Hysteresis_Filter_U0_ap_continue <= ap_const_logic_1;
